script:
"=== auth.json (redacted) ==="
$auth = Get-Content "$env:USERPROFILE\.local\share\opencode\auth.json" | ConvertFrom-Json
$auth.PSObject.Properties.Name
"=== check if token looks valid ==="
$zen = $auth."opencode"
if ($zen) { "Zen auth type: " + $zen.type }
"=== trying with explicit model flag ==="
$job = Start-Job -ScriptBlock {
  $env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
  Set-Location "$env:USERPROFILE\Desktop\audit2"
  opencode run --model "opencode/space-bunny-free" "Say OK" 2>&1 | Select-Object -First 5
}
if (Wait-Job $job -Timeout 30) {
  Receive-Job $job
} else {
  "TIMED OUT"
  Stop-Job $job
}
Remove-Job $job -Force
